package com.crm.customer.entity;import jakarta.persistence.*;import lombok.Data;import java.time.LocalDateTime;
@Entity @Table(name="client_cases") @Data public class ClientCase {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@Column(name="customer_id",nullable=false,updatable=false) private Long customerId;@Column(name="request_id",nullable=false,unique=true,length=36,updatable=false) private String requestId;@Column(nullable=false,length=200,updatable=false) private String subject;@Column(nullable=false,length=4000,updatable=false) private String description;@Column(nullable=false,length=20) private String status="OPEN";@Column(name="created_at",nullable=false,updatable=false) private LocalDateTime createdAt;@PrePersist void created(){createdAt=LocalDateTime.now();}}
